'use strict';
const catalogUI=()=>CATALOG_UI[language];
const catalogItem=id=>HOSPITAL_CATALOG.find(item=>item.id===id||item.code===id);
const catalogName=item=>language==='zh-Hant'?item.zh:CATALOG_NAMES[language][HOSPITAL_CATALOG.indexOf(item)];
function surgeryName(){return SURGERY_NAMES[language][SURGERY_IDS.indexOf(patient?.surgery||'V')];}
function selectedCatalogItems(){return HOSPITAL_CATALOG.filter(item=>careState.selected.has(item.id));}
function itemSymbol(item){if(item.group==='自費藥品')return medicineIcon(item.id);let body='';if(['03','05','08','09','10','11','GI15','GI16'].includes(item.code))body='<rect x="15" y="16" width="70" height="53" rx="8"/><path d="M24 44h12l6-17 10 30 7-13h17M50 69v16m-17 0h34"/>';else if(item.code==='04')body='<rect x="15" y="15" width="70" height="70" rx="9"/><path d="M23 30h54M23 45h54M23 60h54M23 75h54"/>';else if(item.code==='C01')body='<rect x="13" y="24" width="74" height="50" rx="17"/><ellipse cx="50" cy="49" rx="21" ry="12"/>';else if(item.code==='C07'||item.code==='02')body='<path d="M15 20v28q35 32 70 0V20M43 49V36m14 13V36M15 48v33m70-33v33"/>';else if(item.code==='C02')body='<path d="M25 17v36q0 22 23 22h31M21 18h8M58 71v8"/><rect x="20" y="40" width="10" height="17" rx="4"/><path d="M79 70v10"/>';else if(item.code==='C05')body='<rect x="29" y="13" width="43" height="57" rx="8"/><path d="M50 70v20M38 36h24M50 25v24M29 55h43"/>';else if(item.code==='C06')body='<path d="M10 38q15-17 33 0v22H10Zm47 0q17-17 33 0v22H57Z"/><path d="M43 43h14"/>';else if(item.code.startsWith('C'))body='<rect x="16" y="25" width="68" height="49" rx="11"/><rect x="37" y="31" width="26" height="36" rx="5"/><path d="M25 40h3m-3 12h3m44-12h3m-3 12h3"/>';else if(['06','07'].includes(item.code))body='<rect x="14" y="36" width="54" height="44" rx="6"/><path d="M22 50h36m-36 13h36M77 17q-20 23 0 30 20-7 0-30Z"/>';else if(item.code.startsWith('PA')||item.code.startsWith('OB'))body='<rect x="27" y="13" width="46" height="67" rx="8"/><path d="M35 28h30v18H35Zm4 33h22M50 80v12M27 50H15V24"/>';else body='<path d="M25 28q25-20 50 0v42q-25 20-50 0Z"/><path d="M36 47h28m-14-14v28M75 32h12v51"/>';return `<svg viewBox="0 0 100 100" aria-hidden="true"><g fill="#e3eee7" stroke="#6a958b" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">${body}</g></svg>`;}
function setCatalogSelection(id,checked){if(checked)careState.selected.add(id);else careState.selected.delete(id);document.querySelectorAll('input[data-care-id]').forEach(box=>{if(box.dataset.careId===id)box.checked=checked});updateCareSummary();document.querySelectorAll('.catalog-selected-count').forEach(el=>el.textContent=careText().selectedCount.replace('{n}',careState.selected.size));}
function catalogCard(item,onChange){const u=catalogUI(),card=document.createElement('label');card.className='catalog-card';card.dataset.catalogCode=item.code;const box=document.createElement('input');box.type='checkbox';box.dataset.careId=item.id;box.checked=careState.selected.has(item.id);const content=document.createElement('span');content.className='catalog-card-copy';content.innerHTML=`<strong>${esc(catalogName(item))}</strong>${language!=='zh-Hant'?`<small lang="zh-Hant">${esc(u.official)}：${esc(item.zh)}</small>`:''}${item.note&&language==='zh-Hant'?`<small>${esc(item.note)}</small>`:''}`;box.setAttribute('aria-label',u.check+' · '+catalogName(item));box.onchange=()=>{setCatalogSelection(item.id,box.checked);onChange?.(item.id)};card.append(box,content);return card;}
function renderCatalog(root,{room=false,onChange=null}={}){const u=catalogUI(),section=document.createElement('section');section.className='hospital-catalog';section.innerHTML=`<h3>${esc(room?u.other:u.title)}</h3><p class="catalog-selected-count" aria-live="polite">${esc(careText().selectedCount.replace('{n}',careState.selected.size))}</p><p class="hint">${esc(u.reference)}</p>`;
 const bundle=SURGERY_BUNDLES[patient?.surgery||'V'];
 if(!room&&bundle.codes.length){const panel=document.createElement('section');panel.className='bundle-panel';panel.innerHTML=`<h4>${esc(u.bundle)} · ${esc(surgeryName())}</h4><p>${esc(u.bundleNote)}</p><div class="catalog-grid"></div>`;bundle.codes.forEach(code=>panel.querySelector('.catalog-grid').append(catalogCard(catalogItem(code),onChange)));section.append(panel)}
 const search=document.createElement('input');search.type='search';search.className='catalog-search';search.placeholder=u.search;search.setAttribute('aria-label',u.search);section.append(search);const all=document.createElement('div');all.className='catalog-categories';
 CATALOG_GROUPS.forEach((group,index)=>{const list=HOSPITAL_CATALOG.filter(item=>item.group===group),details=document.createElement('details');details.className='catalog-category';details.innerHTML=`<summary>${esc(u.groups[index])}<span>${list.length} ${esc(u.count)}</span></summary><div class="catalog-grid"></div>`;list.forEach(item=>details.querySelector('.catalog-grid').append(catalogCard(item,onChange)));all.append(details)});section.append(all);
 search.oninput=()=>{const q=search.value.trim().toLocaleLowerCase();all.querySelectorAll('.catalog-category').forEach(group=>{let count=0;group.querySelectorAll('.catalog-card').forEach(card=>{const item=catalogItem(card.dataset.catalogCode),match=!q||[item.code,item.zh,catalogName(item)].some(value=>value.toLocaleLowerCase().includes(q));card.hidden=!match;if(match)count++});group.hidden=!count;if(q)group.open=true})};root.append(section);return section;}
function renderRoomCatalog(root){const figure=root.querySelector('.room-illustration');const gallery=document.createElement('section');gallery.className='selected-visuals';gallery.setAttribute('aria-label',catalogUI().figure);gallery.innerHTML=`<h3>${esc(catalogUI().figure)}</h3>`;const selected=selectedCatalogItems();if(!selected.length)gallery.append(textElement('p',catalogUI().empty,'hint'));else{const grid=document.createElement('div');grid.className='selected-visual-grid';selected.forEach(item=>{const card=document.createElement('article');card.dataset.sceneCatalog=item.code;card.innerHTML=itemSymbol(item)+`<div><strong>${esc(catalogName(item))}</strong><p class="item-explanation">${esc(itemExplanation(item))}</p></div>`;grid.append(card)});gallery.append(grid)}figure.append(gallery);
 const chooser=renderCatalog(root,{room:true,onChange:id=>{const dialog=$('#topic-dialog'),scroll=dialog.scrollTop;const expanded=[...root.querySelectorAll('.catalog-category[open]')].map(el=>el.querySelector('summary').textContent);const query=root.querySelector('.catalog-search')?.value||'';renderOperatingRoom(root);root.querySelectorAll('.catalog-category').forEach(el=>el.open=expanded.includes(el.querySelector('summary').textContent));if(query){const search=root.querySelector('.catalog-search');search.value=query;search.dispatchEvent(new Event('input'))}dialog.scrollTop=scroll;root.querySelector(`.hospital-catalog input[data-care-id="${id}"]`)?.focus({preventScroll:true})}});root.querySelector('#scene-back').before(chooser);}
function extraPatientSVG(has){return `${has('05')?'<g id="scene-cerebral-oxygen"><rect x="486" y="330" width="17" height="11" rx="4" fill="#c3b4db"/><rect x="551" y="330" width="17" height="11" rx="4" fill="#c3b4db"/><path d="M568 336Q655 348 700 550" fill="none" stroke="#a197be" stroke-width="2"/></g>':''}${has('C06')?'<g id="scene-eye-protection"><path d="M500 329q9-6 18 0v9h-18Zm35 0q9-6 18 0v9h-18Z" fill="#f1e6db" stroke="#bcb2a7"/></g>':''}${has('C01')?'<g id="scene-head-cushion"><path d="M472 299Q459 323 478 370M577 299Q590 323 577 370" fill="none" stroke="#b5cad4" stroke-width="13" stroke-linecap="round"/></g>':''}${has('C03')||has('C04')||has('C08')?'<g id="scene-dressings"><rect x="470" y="478" width="25" height="25" rx="6" fill="#eee4cb" stroke="#c3b292"/></g>':''}`;}

for(const code of Object.keys(CARE_I18N))CARE_I18N[code].methods[4]=METHOD_GALLERY[code].items[3][0];
